import csv
from collections import defaultdict

ids = {
 'F3Z01': 'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
 'F2Z01': 'baef86cb-2941-5d61-87b0-ffa91d79f23a',
 'F4Z01': '14a08406-79a0-52ca-b8a1-8563259dc820',
 'F1Z01': '7a9e6dea-7214-57d7-a3ab-6fec741ab22a',
}
series = defaultdict(dict)
with open(VALUES_CSV) as f:
    r=csv.DictReader(f)
    for row in r:
        if row['timeseries_id'] in set(ids.values()):
            series[row['timeseries_id']][row['timestamp']] = float(row['value'])

def monthly(sid):
    d=series[sid]
    m=defaultdict(list)
    for ts,v in d.items():
        m[ts[:7]].append(v)
    return {k:sum(v)/len(v) for k,v in m.items()}

def diff(k1,k2):
    a=monthly(ids[k1]); b=monthly(ids[k2])
    return {k: round(a[k]-b[k],2) for k in sorted(a) if k in b}

